class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def findMirror(root: TreeNode, target: int) -> int:
    def find(node, target, is_mirror=False):
        if not node:
            return None, False
        if node.val == target:
            return node, True
        left_result, found_left = find(is_mirror and node.right or node.left, target, is_mirror)
        if found_left:
            return left_result, True
        right_result, found_right = find(is_mirror and node.left or node.right, target, is_mirror)
        if found_right:
            return right_result, True
        return None, False

    target_node, found = find(root, target)
    if not found:
        return -1
    mirror_node, _ = find(root, target_node.val, True)
    return mirror_node.val if mirror_node else -1
